function travel(path: string) {
  document.dispatchEvent(new CustomEvent('glow:navigate', { detail: { path } }));
}
function openGlow(prompt: string) {
  document.dispatchEvent(new CustomEvent('glow:open', { detail: { prefill: prompt } }));
}
function formatClock(seconds: number) {
  const safe = Math.max(0, seconds);
  return `${Math.floor(safe / 60)}:${String(safe % 60).padStart(2, '0')}`;
}
function relativeDate(iso: string) {
  const date = new Date(iso); const diff = Date.now() - date.getTime(); const day = 86400000;
  if (diff < day) return 'Today'; if (diff < day * 2) return 'Yesterday'; if (diff < day * 7) return `${Math.floor(diff / day)} days ago`;
  return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
}

function GlowOrb({ small = false }: { small?: boolean }) {
  return <span className={small ? styles.orbSmall : styles.orb} aria-hidden="true"><i /></span>;
}
function Toggle({ checked, onChange, label }: { checked: boolean; onChange: () => void; label: string }) {
  return <button type="button" role="switch" aria-checked={checked} aria-label={label} onClick={onChange} className={`${styles.switch} ${checked ? styles.switchOn : ''}`}><span /></button>;
}
function PressureDots({ pressure, count = 9 }: { pressure: GuaShaPressure; count?: number }) {
  const active = pressure === 'Light' ? 4 : pressure === 'Medium' ? 6 : count;
  return <span className={styles.pressureDots}>{Array.from({ length: count }, (_, i) => <i key={i} className={i < active ? styles.dotOn : ''} />)}</span>;
}

